(globalThis.CATALOGUE_RECORD_CHUNKS??=Object.create(null))[624]={"source_order":624,"notes":["The superscript letter after 312 is read as 'b', consistent with the folio label, but its letterform is slightly ambiguous.","The faint arc at about y 1400–1470 may be a genuine pencil stroke rather than show-through; no text is associated with it.","Right of the gutter (x ≈ 3130–3160 native) are visible fragments of the facing page, fol. 313: shelfmarks such as 'd. 10..', 'e. 149..', 'f. 36..', 'Ire Agnistom..', ticks and bracket arrows. These are not target-page records and are excluded.","Faint mirror-image show-through of the recto (fol. 312) catalogue entries is visible across the ruled lines. It is not writing on this page and is not transcribed.","I reviewed the overview and all six native tiles, covering the top, middle, bottom, both margins and the gutter. The ruled page has no catalogue entries, headings, cross-references or marginal notes. Its only writing is the folio number '312ᵇ.'.","Faint mirror-image show-through of the fol. 312 recto entries is visible across the ruled lines. It is not writing on this page and was not transcribed.","A faint curved arc stroke appears at about [2780,1400,180,70]. It may be show-through or offset, or possibly a stray pencil stroke. It is not legible text and is not associated with any entry.","Small specks and blots appear at about [500,2590,30,60], [1180,440,70,70] and [2950,4440,40,40]. They are not text.","Right of the gutter (x ≈ 3130 onward) are fragments of the facing page, fol. 313. These include shelfmarks such as 'd. 10..', 'e. 149..', 'f. 36..', 'd. 74..', '√d. 17..', a fragment beginning 'Ire Agnistom..' [reading?], ticks and bracketing arrows. They belong to source_order 625 and are excluded as target records.","The superscript letter after '312' is read as 'b', consistent with the supplied label. Its letterform is slightly ambiguous.","It is unclear whether the faint arc is show-through or offset from another leaf or a genuine stray pencil stroke on this page."],"records":[{"id":"css-prod-0624-r001","local_id":"r001","source_order":624,"folio":"312b","folio_label":"fol. 312b","sequence":1,"page_id":"8086cf0b-9951-41c6-b397-c3780a8d83f6","kind":"other","record_type":"non_catalogue_text","source_model_record_type":"non_catalogue_text","subtype":"folio_number","shelfmark":"","titleLiteral":"","titleNormalized":"","displayTitle":"Catalogue text","authorOrSource":"","source":"","subject":"","subjectGroup":"","date":"","extent":"","lines":"","script":"","incipit":"","transcription":"312ᵇ.","annotations":["Written in the top-left margin, left of the ruled vertical margin line, in dark pencil or ink.","The 'b' is superscript above and right of '312'. A point follows the numeral."],"uncertainties":["The superscript letter is read as 'b'. This matches the supplied label fol. 312b, but the letterform is slightly ambiguous.","The superscript letter after '312' is read as 'b', consistent with the supplied label. Its letterform is slightly ambiguous.","It is unclear whether the faint arc is show-through or offset from another leaf or a genuine stray pencil stroke on this page."],"focused_readings":[],"reviewNotes":[],"editorialNotes":[],"relationships":[],"editorial_context":[],"block_ids":["b001"],"locations":[{"block_id":"b001","bbox":[435,365,165,135]}],"isCancelled":false,"needsReview":true,"human_verified":false,"verification_status":"machine_reviewed","change_audit":[],"sourceCitationURL":"https://iiif.bodleian.ox.ac.uk/iiif/canvas/8086cf0b-9951-41c6-b397-c3780a8d83f6.json","auditPath":"audit/pages/0624.json","attachedNotes":[],"resolvedRelationships":[],"attachedRecords":[]}]};
